def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // math.gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

def is_korean(sequence):
    n = len(sequence)
    if n < 2:
        return False

    # Check strict increase (already handled by generation, but good practice)
    for i in range(n - 1):
        if sequence[i] >= sequence[i+1]:
            return False

    # Check all partitions k=1 to n-1
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        L_k = lcm_list(A_k)
        G_k = gcd_list(B_k)

        if L_k != G_k:
            return False

    return True

def search_for_korean_sequences(n, max_element=10):
    found_sequences = []
    print(f"--- Searching for Korean sequences of length n={n} (elements <= {max_element}) ---")

    # Generate all strictly increasing sequences of length n using numbers up to max_element
    # We use a combination generation approach to ensure strict increase

    from itertools import combinations

    elements = list(range(1, max_element + 1))

    for seq_tuple in combinations(elements, n):
        sequence = list(seq_tuple)

        if is_korean(sequence):
            # If it is Korean, it has n-1 good partitions by definition.
            num_good_partitions = n - 1
            print(f"FOUND sequence: {sequence}. Number of good partitions: {num_good_partitions}")
            found_sequences.append((sequence, num_good_partitions))

    return found_sequences

